.marquee-container:hover div {
    animation-play-state: var(--pause-on-hover)
}

.marquee-container:active div {
    animation-play-state: var(--pause-on-click)
}

.overlay:after,
.overlay:before {
    background: linear-gradient(to right, var(--gradient-color));
    content: "";
    height: 100%;
    position: absolute;
    width: var(--gradient-width);
    z-index: 2
}

.overlay:after {
    right: 0;
    top: 0;
    transform: rotate(180deg)
}

.overlay:before {
    left: 0;
    top: 0
}

@keyframes scroll {
    0% {
        transform: translateX(0)
    }

    to {
        transform: translateX(-100%)
    }
}

.link-cards-wrapper {
    flex-wrap: wrap;
    gap: 12px;
    padding: 16px
}

.link-card,
.link-cards-wrapper {
    display: flex;
    justify-content: center
}

.link-card {
    align-items: center;
    flex-direction: column;
    padding: 24px;
    background: var(--background-color-1);
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .08);
    text-decoration: none;
    color: #fff;
    font-weight: 500;
    font-size: 14px;
    transition: all .2s ease;
    width: 13%;
    min-width: 100px;
    text-align: center
}

.link-card img {
    height: 54px;
    object-fit: contain;
    width: 54px
}

@media (max-width:1023px) {
    .hide-on-mobile {
        display: none
    }

    .link-card {
        width: 23%;
        min-width: 160px
    }
}

.promo-grid {
    display: grid;
    grid-template-columns: repeat(6, 2fr);
    gap: 16px;
    max-width: calc(100vw - 100px);
    margin: 0 auto;
    padding: 16px
}

.promo-card {
    display: block;
    border-radius: 12px;
    overflow: hidden;
    transition: transform .25s ease, box-shadow .25s ease;
    text-decoration: none;
    background-color: transparent
}

.promo-card-featured {
    grid-column: span 2;
    grid-row: span 2
}

.promo-card img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover
}

@media (max-width:1023px) {
    .promo-grid {
        display: grid;
        overflow: hidden;
        grid-template-columns: repeat(2, 2fr);
        gap: 16px;
        max-width: calc(100vw - 100px);
        margin: 0 auto;
        padding: 16px
    }

    .promo-grid::-webkit-scrollbar {
        height: 4px
    }

    .promo-grid::-webkit-scrollbar-thumb {
        background: #ccc;
        border-radius: 4px
    }

    .promo-card {
        flex: 0 0 70%;
        scroll-snap-align: start;
        border-radius: 12px;
        grid-column: span 1;
        grid-row: span 1
    }

    .promo-card.mobile-hidden {
        display: none
    }

    .promo-card img {
        height: auto;
        aspect-ratio: 16/9
    }
}

.casino-grid {
    display: grid;
    grid-template-columns: repeat(6, 2fr);
    gap: 16px;
    max-width: calc(100vw - 100px);
    margin: 0 auto;
    padding: 16px
}

.casino-card {
    display: block;
    border-radius: 12px;
