.tb--w_100 {
    width: 100%
}

.tb--h_100 {
    height: 100%
}

.tb--h_fc {
    height: -webkit-fit-content;
    height: fit-content
}

.tb--tac {
    text-align: center
}

.tb--tar {
    text-align: right
}

.tb--text_upercase {
    text-transform: uppercase
}

.tb--text-capitalize {
    text-transform: capitalize
}

.tb--nowrap {
    white-space: nowrap
}

.tb--cp {
    cursor: pointer
}

.tb--cd {
    cursor: default
}

.tb--ellipsis {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}
.tb--flex-grow {
    flex-grow: 1;
}
.tb--pr-12 {
    padding-right: 12px;
}
.tb--block {
    display: block
}

.fade--in {
    opacity: 1;
    pointer-events: auto
}

.fade--out {
    opacity: 0;
    pointer-events: none
}

.tb--f-medium {
    font-weight: 500
}

.tb--bold {
    font-weight: 700
}

.tb--fs-small {
    font-size: 12px
}

.tb--title:before {
    background: var(--background-color-1);
    background-image: var(--background-gradient-1);
    border-radius: 4px;
    content: "";
    display: inline-block;
    height: 100%;
    left: 0;
    opacity: .9;
    position: absolute;
    top: 0;
    width: 100%;
    z-index: -1
}

.tb--profile-scroll {
    overflow-x: hidden;
    overflow-y: auto
}

.tb--table-container {
    flex: 1 1
}

.two-level-table_container {
    border-radius: 12px;
    flex: 1 1
}

.table-height {
    flex: 1 1
}

.tb--flex-wrap {
    flex-wrap: wrap
}

.tb--history-filter .tb--pay-inner-input {
    margin-bottom: 12px
}

.fade-exit {
    opacity: 1
}

.fade-exit-done {
    opacity: 0
}

.tb--status:after {
    background-color: #af61ec;
    border-radius: 10px 10px 10px 0;
    bottom: 0;
    content: "";
    left: 0;
    opacity: .2;
    position: absolute;
    right: 0;
    top: 0;
    z-index: -1
}

.tb--status.tb--status-new:after {
    background-color: #8480e8
}

.tb--status.tb--status-answered:after {
    background-color: #93b044
}

.tb--gap-12 {
    gap: 12px
}

.lm-status:before {
    height: 10px;
    left: 0;
    opacity: .5;
    top: 0;
    width: 10px
}

.tb--radius-btn {
    border-radius: var(--btn-radius-top-left) var(--btn-radius-top-right) var(--btn-radius-bottom-right) var(--btn-radius-bottom-left)
}

.tb--rtl .tb--status:after {
    border-radius: 10px 10px 0 10px
}

