.dropdown {
    cursor: pointer;
    font-size: 12px;
    height: 40px;
    line-height: 40px;
    position: relative
}

.dropdown .dropdown_item:hover {
    background-color: var(--inputBgHover);
    color: var(--inputTxt)
}

.filter {
    display: flex;
    flex-direction: column;
    min-width: 100px
}

.print_selection_widget .print_selection_content .print_selection_rows_wrapper:empty:before {
    color: var(--widgetTxt2);
    content: "no data yet";
    font-size: 16px;
    text-transform: capitalize
}

@media print {
    @page {
        size: landscape
    }
}

.board_row-tournament:hover,
.board_row:hover {
    background-color: var(--dominantBgHover);
    color: var(--dominantTxt)
}

.print_template_row:hover .sport_front_icon-circle_close {
    color: var(--errorBg)
}

.dg_preserve_ltr {
    unicode-bidi: embed !important
}

.jackpot_slider_wrapper .sport_front_icon-issue:before {
    font-size: var(--fsz28)
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0
}

.dg_jackpot {
    --amethystBg: #fc0c4d;
    --emeraldBg: #5aae73;
    --goldBg: #f88543;
    --diamondBg: #197eb4;
    --jp-shine-border-angle: 185deg;
    --jp-shine-angle: 35deg;
    --jp-mask-x: right
}

.dg_jackpot .dg_jackpot_slider {
    box-sizing: border-box;
    column-gap: 0;
    display: flex;
    height: 72px;
    padding: 0 16px
}

.dg_jackpot .dg_jackpot_slider .swiper-lock {
    pointer-events: none
}

.dg_jackpot .dg_jackpot_slider_item {
    flex-basis: 280px;
    flex-grow: 1;
    flex-shrink: 1;
    max-width: 410px;
    min-width: 280px
}

.dg_jackpot .dg_jackpot_slider_item:hover .dg_jackpot_info {
    height: 100%;
    opacity: 1;
    transform: scaleY(1);
    transform-origin: top;
    transition: opacity .18s ease-out, transform .18s ease-out;
    z-index: 9
}

.dg_jackpot.dg_jackpot_landing_static .dg_jackpot_slider_item:hover .dg_jackpot_info {
    height: 0;
    opacity: 0;
    transform: scaleY(0);
    z-index: 1
}

.dg_jackpot .dg_jackpot_preserve_ltr {
    direction: ltr !important
}

.dg_jackpot .dg_jackpot_separator {
    align-items: center;
    background: var(--eventTxt2);
    border-radius: 50%;
    display: flex;
