    0% {
        opacity: 0;
        transform: translate3d(0, -46px, 0)
    }

    to {
        opacity: 1;
        transform: translateZ(0)
    }
}

.bh_notif_icon:after {
    background-color: #fff;
    border-radius: 50%;
    content: "";
    display: block;
    height: 60%;
    left: 50%;
    position: absolute;
    top: 50%;
    transform: translate(-50%, -50%);
    width: 60%;
    z-index: -1
}

.bh_notif_icon_wrap:after,
.bh_notif_icon_wrap:before {
    border-radius: inherit;
    color: currentColor;
    content: "";
    display: block;
    height: 100%;
    left: 0;
    position: absolute;
    top: 0;
    width: 100%;
    z-index: -1
}

