}

.bh_wrapper .dg_boosted_bicolor_icon:before {
    --size: calc(var(--icoSize) - 4px);
    background-color: var(--eventAccent);
    border-radius: inherit;
    content: "";
    display: block;
    height: var(--size);
    left: 50%;
    opacity: .2;
    position: absolute;
    top: 50%;
    transform: translate(-50%, -50%);
    width: var(--size);
    z-index: 1
}

.bh_root :after,
.bh_root :before {
    box-sizing: border-box
}

button:focus {
    outline: none !important
}

.bh_skeleton:after {
    animation: bh_skeleton_shimmer 1.4s linear 99;
