:root {
    --color-mode-trans-dur: 250ms
}

html body::-webkit-scrollbar,html body::-webkit-scrollbar-thumb {
    -webkit-transition: none!important;
    transition: none!important
}

html body.theme-switching::-webkit-scrollbar {
    background-color: #e6e6e680!important
}

html body.theme-switching::-webkit-scrollbar-thumb {
    background-color: #cccccc80!important
}

html body.theme-switching {
    transition-duration: 125ms;
    transition-duration: calc(var(--color-mode-trans-dur)*.5)
}

html body.theme-switching img {
    background-color: #0000
}

html body.theme-switching .search-block,html body.theme-switching canvas,html body.theme-switching embed,html body.theme-switching iframe,html body.theme-switching img,html body.theme-switching input,html body.theme-switching object,html body.theme-switching picture,html body.theme-switching svg,html body.theme-switching textarea,html body.theme-switching video {
    transition: none!important
}

.color-mode label {
    -webkit-tap-highlight-color: rgba(0,0,0,0);
    background-color: var(--background-color-2);
    border-radius: 24px;
    box-sizing: border-box;
    cursor: pointer;
    display: block;
    height: 28px;
    min-height: 28px;
    min-width: 60px;
    outline: #0000;
    perspective: 1000px;
    position: relative;
    transition: background-color;
    width: 60px
}

.color-mode label,.color-mode label:after {
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
    transform: translateZ(0)
}

.color-mode label:after {
    background-color: var(--background-color-1);
    border-radius: 50%;
    box-shadow: 0 2px 4px #0000001f,inset 0 -1px 4px #0000001f;
    content: "";
    height: 23px;
    left: 2px;
    position: absolute;
    top: 2px;
    transition: transform .25s ease-in-out,box-shadow .15s;
    transition: transform var(--color-mode-trans-dur) ease-in-out,box-shadow calc(var(--color-mode-trans-dur)*.6);
    width: 23px
}

.color-mode label .digi_icon-light {
    color: var(--brand-color-2);
    font-size: 20px;
    opacity: 1;
    right: 4px
}

.color-mode label .digi_icon-dark,.color-mode label .digi_icon-light {
    pointer-events: none;
    position: absolute;
    top: 2px;
    transition: opacity .25s linear;
    transition: opacity calc(var(--color-mode-trans-dur)) linear;
    will-change: opacity
}

.color-mode label .digi_icon-dark {
    color: var(--background-color-1);
    font-size: 22px;
    left: 4px;
    opacity: .6
}

.color-mode input {
    -webkit-appearance: none;
    appearance: none;
    display: none;
    height: 0;
    visibility: hidden;
    width: 0
}

.color-mode input:checked+label {
    background-color: var(--brand-color-2)
}

.color-mode input:checked+label:after {
    background-color: var(--text-color-1);
    box-shadow: 0 2px 4px #0000001f;
    transform: translateX(32px) translateZ(0)
}

.color-mode input:checked+label .digi_icon-light {
    opacity: .6
}

.color-mode input:checked+label .digi_icon-dark {
    opacity: 1
}


.game-history-filter {
    align-items: end;
    background: #211f42;
    border-radius: 16px 16px 0 0;
    display: grid;
    gap: 12px;
    grid-template-columns: minmax(220px, 1fr) minmax(220px, 1fr) minmax(220px, 1fr) minmax(160px, .5fr);
    padding: 22px 26px 18px;
    position: relative;
    z-index: 5;
}

.game-history-filter__field {
    display: flex;
    flex-direction: column;
    min-width: 0;
    position: relative;
}

.game-history-filter__label {
    color: #fff;
    font-size: 14px;
    font-weight: 500;
    line-height: 18px;
    margin: 0 0 6px;
}

.game-history-filter__select,
.game-history-filter__date,
.game-history-filter__submit {
    border: 0;
    border-radius: 7px;
    box-sizing: border-box;
    font: inherit;
    height: 52px;
}

.game-history-filter__select,
.game-history-filter__date {
    align-items: center;
    background: #111126;
    color: #fff;
    display: flex;
    font-size: 17px;
    font-weight: 500;
    justify-content: space-between;
    padding: 0 18px;
    text-align: left;
    width: 100%;
}

.game-history-filter__select {
    cursor: pointer;
    outline: 1px solid transparent;
}

.game-history-filter__select:focus-visible,
.game-history-filter__select.is-open {
    outline-color: #595caa;
}

.game-history-filter__select i {
    color: #696dc0;
    flex: 0 0 auto;
    font-size: 18px;
    margin-left: 12px;
    transition: transform .2s ease;
}

.game-history-filter__select.is-open i {
    transform: rotate(180deg);
}

.game-history-filter__menu {
    background: #111126;
    border-radius: 0 0 7px 7px;
    box-shadow: 0 8px 18px rgba(0, 0, 0, .22);
    left: 0;
    list-style: none;
    margin: 4px 0 0;
    max-height: 250px;
    overflow-y: auto;
    padding: 0;
    position: absolute;
    right: 0;
    top: 76px;
    z-index: 20;
}

.game-history-filter__menu li {
    color: rgba(255, 255, 255, .58);
    cursor: pointer;
    font-size: 16px;
    line-height: 20px;
    padding: 11px 16px;
}

.game-history-filter__menu li:hover,
.game-history-filter__menu li:focus,
.game-history-filter__menu li.is-selected {
    background: #222043;
    color: #fff;
}

.game-history-filter__date {
    cursor: pointer;
    overflow: hidden;
    position: relative;
}

.game-history-filter__date i {
    color: rgba(255, 255, 255, .58);
    font-size: 21px;
}

.game-history-filter__date input {
    cursor: pointer;
    height: 100%;
    inset: 0;
    opacity: 0;
    position: absolute;
    width: 100%;
}

.game-history-filter__date input::-webkit-calendar-picker-indicator {
    cursor: pointer;
    height: 100%;
    inset: 0;
    position: absolute;
    width: 100%;
}

.game-history-filter__submit {
    background: #6065b1;
    color: #fff;
    cursor: pointer;
    font-size: 17px;
    font-weight: 500;
    padding: 0 24px;
    transition: background-color .2s ease;
    width: 100%;
}

.game-history-filter__submit:hover {
    background: #7076c5;
}

.game-history-filter__submit:focus-visible {
    outline: 2px solid #aeb1ff;
    outline-offset: 2px;
}

@media (max-width: 1023px) {
    .game-history-filter {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 600px) {
    .game-history-filter {
        border-radius: 12px;
        grid-template-columns: 1fr;
        padding: 16px;
    }

    .game-history-filter__select,
    .game-history-filter__date,
    .game-history-filter__submit {
        height: 48px;
    }

    .game-history-filter__menu {
        top: 72px;
    }
}


