    .lq-mobile-filter-sheet__radios button {
        align-items: center;
        background: transparent;
        color: var(--modal-text-color-1);
        display: flex;
        font-size: 15px;
        justify-content: space-between;
        min-height: 47px;
        padding: 0;
        text-align: left;
        width: 100%
    }

    .lq-mobile-filter-sheet__radios button.active {
        color: var(--brand-color-2)
    }

    .lq-mobile-filter-sheet__radio {
        border: 1px solid rgb(255 255 255 / 35%);
        border-radius: 50%;
        box-sizing: border-box;
        height: 20px;
        position: relative;
        width: 20px
    }

    .lq-mobile-filter-sheet__radios button.active .lq-mobile-filter-sheet__radio {
        border-color: var(--brand-color-2)
    }

    .lq-mobile-filter-sheet__radios button.active .lq-mobile-filter-sheet__radio:after {
        background: var(--brand-color-2);
        border-radius: 50%;
        content: "";
        inset: 4px;
        position: absolute
    }

    .lq-mobile-filter-sheet__chips {
        display: flex;
        flex-wrap: wrap;
        gap: 10px
    }

    .lq-mobile-filter-sheet__chips button {
        background: var(--modal-bg-color-1);
        border: 1px solid transparent;
        border-radius: 10px;
        color: var(--modal-text-color-1);
        font-size: 12px;
        min-height: 40px;
        padding: 8px 18px;
        text-transform: none
    }

    .lq-mobile-filter-sheet__chips button.active {
        border-color: rgb(255 255 255 / 65%);
        color: #fff;
        font-weight: 600
    }

    .lq-mobile-filter-sheet__more {
        background: transparent;
        color: var(--brand-color-2);
        display: block;
        font-size: 15px;
        margin: 15px auto 0;
        padding: 0;
        text-decoration: underline
    }

    .lq-mobile-filter-sheet__footer {
        background: var(--modal-bg-color-1);
        border-top: 1px solid rgb(255 255 255 / 9%);
        display: grid;
        flex: 0 0 auto;
