    .lq-mobile-filter-sheet__footer button {
        border-radius: 9px;
        font-size: 16px;
        height: 55px
    }

    .lq-mobile-filter-sheet__reset {
        background: transparent;
        border: 1px solid var(--brand-color-2);
        color: var(--brand-color-2)
    }

    .lq-mobile-filter-sheet__apply {
        background: var(--brand-color-2);
        color: #fff
    }

    .root-container.mobile .tb--filter-block_wrapper {
