@media screen and (max-width: 520px) {
    .lq-mobile-header__logo.logoBlock {
        flex-basis: 135px;
        margin: 0 4px
    }

    .lq-mobile-header__logo .logoBlock_img {
        max-width: 135px
    }

    .lq-mobile-header__actions {
        gap: 4px !important
    }

    .lq-mobile-header__deposit {
        height: 34px;
