    }

    .lq-mobile-header__balance {
        font-size: 12px;
        height: 34px;
        min-width: 72px;
        padding: 0 6px !important
    }

    .lq-mobile-header__balance small {
        font-size: 10px
    }

    .lq-mobile-nav .mobile-nav_item-inner {
        font-size: 9px
    }

